#ifndef CG4002_NN_PARAMS_HPP
#define CG4002_NN_PARAMS_HPP

// selected_width.hpp is generated by the export and names the width it chose,
// so no hand-written file here has to. -DNN_WIDTH=<n> still overrides it,
// which is how a sweep builds a width the export did not select.
#include "selected_width.hpp"

#ifndef NN_WIDTH
#define NN_WIDTH NN_WIDTH_SELECTED
#endif

#define NN_CAT_(a, b)  a##b
#define NN_CAT(a, b)   NN_CAT_(a, b)
#define NN_STR_(x)     #x
#define NN_STR(x)      NN_STR_(x)

#include NN_STR(NN_CAT(params_w, NN_WIDTH).hpp)

#if NN_W != NN_WIDTH
#error "params_w<N>.hpp disagrees with NN_WIDTH: regenerate the headers."
#endif

#endif  // CG4002_NN_PARAMS_HPP
